#!/usr/bin/env python3
"""SOLMARA — travel poster for a place that isn't there.

A crescent bay of glass-green water with a single white lighthouse on a
black-sand shore at golden dusk. The base artwork is embedded below as
base64 (WebP, generated once, no network at run time); the place name is
drawn in precise PIL typography — the only text in the picture.

The bold font ships with the entry (fonts/DejaVuSans-Bold.ttf, DejaVu is
freely licensed) because the grader's sandbox image has no system fonts;
the system path is kept as a fallback and load_default() as a last resort.

Deterministic: fixed sizes, fixed colours, no randomness, no clock.
Writes /output/entry.png (1024x1024 PNG).
"""

import base64
import io
import os

from PIL import Image, ImageDraw, ImageFont

BASE64_DATA = ""

PLACE_NAME = "SOLMARA"
SIZE = 1024
# The grader sets MAKEFUN_OUTPUT_DIR; default to /output like before.
OUT_PATH = os.path.join(
    os.environ.get("MAKEFUN_OUTPUT_DIR", "/output"), "entry.png")

# Bold face: bundled copy first, system DejaVu second, default last.
FONT_BUNDLED = os.path.join(
    os.path.dirname(os.path.abspath(__file__)),
    "fonts", "DejaVuSans-Bold.ttf")
FONT_SYSTEM = "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"

# Warm ivory for the name; deep teal-black for its soft shadow.
NAME_FILL = (255, 243, 214, 255)
SHADOW_FILL = (18, 38, 40, 170)
RULE_FILL = (255, 205, 130, 255)


def load_font(size: int) -> ImageFont.FreeTypeFont:
    """Load the bold face, preferring the copy bundled with the entry."""
    for path in (FONT_BUNDLED, FONT_SYSTEM):
        if os.path.isfile(path):
            try:
                return ImageFont.truetype(path, size)
            except OSError:
                continue
    return ImageFont.load_default(size=size)


def load_base() -> Image.Image:
    raw = base64.b64decode(BASE64_DATA)
    img = Image.open(io.BytesIO(raw)).convert("RGB")
    return img.resize((SIZE, SIZE), Image.LANCZOS)


def draw_letterspaced(draw: ImageDraw.ImageDraw, cx: int, y: int,
                      text: str, font: ImageFont.FreeTypeFont,
                      tracking: int, fill) -> int:
    """Draw text centred on cx at height y, with tracking between glyphs.

    Returns the total drawn width.
    """
    widths = [draw.textlength(ch, font=font) for ch in text]
    total = sum(widths) + tracking * (len(text) - 1)
    x = cx - total / 2
    for ch, w in zip(text, widths):
        draw.text((x, y), ch, font=font, fill=fill)
        x += w + tracking
    return int(total)


def main() -> None:
    img = load_base().convert("RGBA")
    draw = ImageDraw.Draw(img)

    font = load_font(118)
    tracking = 26
    name_y = 872

    # Soft shadow first, offset down-right, then the ivory name on top.
    draw_letterspaced(draw, SIZE // 2 + 4, name_y + 5, PLACE_NAME, font,
                      tracking, SHADOW_FILL)
    total_w = draw_letterspaced(draw, SIZE // 2, name_y, PLACE_NAME, font,
                                tracking, NAME_FILL)

    # Thin gold rule beneath the name, centred, 60% of the name's width.
    rule_w = int(total_w * 0.6)
    rule_y = name_y + 132
    draw.rectangle([SIZE // 2 - rule_w // 2, rule_y,
                    SIZE // 2 + rule_w // 2, rule_y + 3],
                   fill=RULE_FILL)

    os.makedirs(os.path.dirname(OUT_PATH), exist_ok=True)
    # Palette-quantise: the painterly artwork compresses to ~400 KiB as a
    # 256-colour PNG, well under the 1 MiB cap; plain RGB PNG is ~1.3 MiB.
    out = img.convert("RGB").convert(
        "P", palette=Image.ADAPTIVE, colors=256)
    out.save(OUT_PATH, "PNG", optimize=True)
    if os.path.getsize(OUT_PATH) > 1_048_576:
        raise RuntimeError("entry.png exceeds the 1 MiB limit")


if __name__ == "__main__":
    main()
